    let fixture:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🛠️modeling/🔣️.json")).unwrap();let case=&fixture["tangentJobs"];let positions=serde_json::from_value::<Vec<[f32;3]>>(case["positions"].clone()).unwrap();let faces=serde_json::from_value::<Vec<Vec<u32>>>(case["faces"].clone()).unwrap();let matrix=std::array::from_fn(|id|case["matrix"][id].as_f64().unwrap());let original=DslValue::Array(case["tangent"].as_array().unwrap().iter().map(|value|DslValue::float(value.as_f64().unwrap())).collect());
    for domain in [MeshAttributeDomain::Vertex,MeshAttributeDomain::Corner,MeshAttributeDomain::Face] {let mut mesh=HalfedgeMesh::from_faces(&positions,&faces).unwrap();let count=match domain {MeshAttributeDomain::Vertex=>mesh.vertex_count(),MeshAttributeDomain::Face=>mesh.face_count(),_=>mesh.halfedge_count()};mesh.set_attribute("tangent".into(),MeshAttribute {domain,semantic:MeshAttributeSemantic::Custom,interpolation:MeshAttributeInterpolation::Linear,values:vec![original.clone()],indices:Some(vec![0;count])}).unwrap();let output=mesh.affine_transform_job(matrix).unwrap().finish_with_progress(|_|true).unwrap();let tangent=&output.attributes()["tangent"];assert_eq!(tangent.values.len(),1);let values=tangent.value_at(0).unwrap().as_array().unwrap();for axis in 0..4 {assert!((values[axis].as_f64().unwrap()-case["expected"][axis].as_f64().unwrap()).abs()<1e-12);}}
    for domain in [MeshAttributeDomain::Vertex,MeshAttributeDomain::Corner] {
        let mut mesh=HalfedgeMesh::from_faces(&positions,&faces).unwrap();let count=if domain==MeshAttributeDomain::Vertex {mesh.vertex_count()}else {mesh.halfedge_count()};mesh.set_attribute("tangent".into(),MeshAttribute {domain,semantic:MeshAttributeSemantic::Custom,interpolation:MeshAttributeInterpolation::Linear,values:vec![original.clone()],indices:Some(vec![0;count])}).unwrap();
        let make=||mesh.scale_components_job(vec![VertexId(0)],Vec::new(),Vec::new(),Vec3([-2.0,1.0,3.0]),Some(Vec3::ZERO)).unwrap();let mut job=make();assert!(matches!(job.step(0).unwrap(),MeshModelingStep::Working(_)));let mut phases=std::collections::BTreeMap::new();let output=loop {let before=job.progress();match job.step(1).unwrap() {MeshModelingStep::Working(_)=>{phases.entry(before.phase).or_insert(before.units_done);},MeshModelingStep::Done(mesh)=>break mesh,_=>unreachable!()}};let channel=&output.attributes()["tangent"];assert_eq!(channel.values.len(),2);
        for id in 0..count {let affected=if domain==MeshAttributeDomain::Vertex {id==0}else {mesh.halfedges[id].vertex==0};let value=channel.value_at(id).unwrap();if affected {for axis in 0..4 {assert!((value.as_array().unwrap()[axis].as_f64().unwrap()-case["expected"][axis].as_f64().unwrap()).abs()<1e-12);}}else {assert_eq!(value,&original);}}
        for (_,units) in phases {let mut cancelled=make();assert!(matches!(cancelled.step(units+1).unwrap(),MeshModelingStep::Working(_)));let before=cancelled.progress();cancelled.cancel();assert!(matches!(cancelled.step(1000).unwrap(),MeshModelingStep::Cancelled(progress) if progress==before));}
        assert_eq!(mesh.attributes()["tangent"].values,vec![original.clone()]);println!("[DEBUG] Tangent indexed selected {domain:?} aliases split by domain, units={}",job.progress().units_done);
    }
    let mut mesh=HalfedgeMesh::from_faces(&positions,&faces).unwrap();mesh.set_attribute("tangent".into(),MeshAttribute {domain:MeshAttributeDomain::Face,semantic:MeshAttributeSemantic::Custom,interpolation:MeshAttributeInterpolation::Linear,values:vec![original.clone()],indices:Some(vec![0;mesh.face_count()])}).unwrap();let source=mesh.to_json().unwrap();assert!(mesh.scale_components_job(vec![VertexId(0)],Vec::new(),Vec::new(),Vec3([-2.0,1.0,3.0]),Some(Vec3::ZERO)).unwrap().finish_with_progress(|_|true).is_err());assert_eq!(mesh.to_json().unwrap(),source);
    for (domain,semantic,value) in [(MeshAttributeDomain::Edge,MeshAttributeSemantic::Custom,original.clone()),(MeshAttributeDomain::Vertex,MeshAttributeSemantic::Normal,original.clone()),(MeshAttributeDomain::Vertex,MeshAttributeSemantic::Custom,DslValue::Array(vec![DslValue::float(0.0),DslValue::float(0.0),DslValue::float(0.0),DslValue::float(1.0)])),(MeshAttributeDomain::Vertex,MeshAttributeSemantic::Custom,DslValue::Array(vec![DslValue::float(1.0),DslValue::float(0.0),DslValue::float(0.0),DslValue::float(0.0)]))] {let count=if domain==MeshAttributeDomain::Vertex {mesh.vertex_count()}else {mesh.halfedge_count()};assert!(mesh.set_attribute("tangent".into(),MeshAttribute {domain,semantic,interpolation:MeshAttributeInterpolation::Linear,values:vec![value],indices:Some(vec![0;count])}).is_err());}assert_eq!(mesh.to_json().unwrap(),source);
    println!("[DEBUG] Canonical tangent uses forward affine direction and determinant handedness across Vertex/Corner/Face indexed domains");
}
